<template><div><PageHeader title="Create course" description="Build a publish-ready course catalog entry."><template #actions><RouterLink to="/app/courses" class="btn secondary">Cancel</RouterLink></template></PageHeader><div class="stepper"><div class="step active"><span class="num">1</span> Basics</div><div class="step active"><span class="num">2</span> Objectives</div><div class="step active"><span class="num">3</span> Curriculum</div><div class="step active"><span class="num">4</span> Materials</div><div class="step"><span class="num">5</span> Publish</div></div><div class="card"><div class="form-section"><h3>Basic information</h3><p>Define the course identity and delivery expectations.</p><div class="form-grid"><div class="field"><label>Course name</label><input class="input" v-model="form.name"></div><div class="field"><label>Course code</label><input class="input" v-model="form.code"></div><div class="field"><label>Category</label><select class="select" v-model="form.category"><option>Development</option><option>Security</option><option>Cloud</option><option>Leadership</option><option>Other</option></select></div><div class="field"><label>Duration (hours)</label><input class="input" type="number" v-model="form.duration"></div><div class="field"><label>Level</label><select class="select" v-model="form.level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div><div class="field"><label>Status</label><select class="select" v-model="form.status"><option>draft</option><option>active</option></select></div></div></div><div class="form-section"><h3>Description</h3><p>Write a concise, outcome-focused course summary.</p><div class="field"><label>Course description</label><textarea class="textarea" v-model="form.description" rows="5"></textarea></div></div><div class="form-section"><h3>Learning objectives</h3><p>Add the skills learners should have after completion.</p><div class="notice-list"><div v-for="(obj,i) in form.objectives" :key="i" style="display:flex;gap:8px"><input class="input" v-model="form.objectives[i]"><button class="btn danger small" @click="form.objectives.splice(i,1)">Remove</button></div><button class="btn secondary small" @click="form.objectives.push('')">+ Add objective</button></div></div><div class="form-section"><h3>Curriculum</h3><p>Create the module structure.</p><div class="notice-list"><div v-for="(module,i) in form.modules" :key="i" class="notice-item"><span class="course-icon" style="width:30px;height:30px">{{String(i+1).padStart(2,'0')}}</span><input class="input" v-model="module.name"><button class="btn danger small" @click="form.modules.splice(i,1)">Remove</button></div><button class="btn secondary small" @click="form.modules.push({name:'New module'})">+ Add module</button></div></div><div class="form-actions"><button class="btn secondary" @click="save(true)">Save draft</button><button class="btn primary" @click="save(false)">Publish course</button></div></div></div></template>
<script setup lang="ts">import {reactive} from 'vue';import {useRouter} from 'vue-router';import PageHeader from '../components/PageHeader.vue';import {useToast} from '../composables/useToast';const router=useRouter();const {push}=useToast();const form=reactive({name:'Laravel Fundamentals',code:'LAR-101',category:'Development',duration:24,level:'Intermediate',status:'draft',description:'A production-minded Laravel course covering architecture, routing, databases, authentication and APIs.',objectives:['Build a Laravel application from scratch','Design REST APIs','Implement authentication'],modules:[{name:'Introduction'},{name:'Laravel Architecture'},{name:'Routing'},{name:'Database'},{name:'Authentication'}]});function save(draft:boolean){form.status=draft?'draft':'active';push(draft?'Course draft saved.':'Course published successfully.');router.push('/app/courses')}</script>
